__constant__ uint32_t rowaxis[256],colaxis[256];__constant__ float fp4[15],scales[126];
__host__ __device__ uint32_t mix(uint32_t x){x^=x>>16;x*=0x7feb352dU;x^=x>>15;x*=0x846ca68bU;x^=x>>16;return x;}
struct Input{int w0,a0,w1,a1;uint32_t ctx;};
__device__ Input input(int i){uint32_t h=mix(i+17),j=mix(h+43),w=rowaxis[i/256],act=colaxis[i%256];int al0=h%126,al1=j%126,ga=(h>>12)&15,be=(j>>12)&15,role=(h>>24)%3;return {int(w%81),int(act%225),int(w/81),int(act/225),uint32_t(al0|(al1<<7)|(ga<<14)|(be<<18)|(role<<22))};}
__device__ void dots(int w,int a,float&g,float&u){int gw=w%9,uw=w/9;float x=fp4[a%15],y=fp4[a/15];g=x*(gw%3-1)+y*(gw/3-1);u=x*(uw%3-1)+y*(uw/3-1);}
__device__ uint32_t finish(float g0,float u0,float g1,float u1,uint32_t ctx){float a0=scales[ctx&127],a1=scales[(ctx>>7)&127],gamma=1.f+float((ctx>>14)&15)*.0625f,beta=1.f+float((ctx>>18)&15)*.0625f;int down=int(ctx>>22)-1;float g=(g0*a0+g1*a1)*gamma,u=(u0*a0+u1*a1)*beta;float y=((g/(1.f+__expf(-g)))*u)*down;return uint32_t(max(-127,min(127,__float2int_rn(y))));}
__device__ uint32_t source(Input in,uint32_t&expected){float g0,u0,g1,u1;dots(in.w0,in.a0,g0,u0);dots(in.w1,in.a1,g1,u1);int n=int(2*g0)+64*int(2*u0)+4096*int(2*g1)+262144*int(2*u1);expected=__float_as_uint(float(n));return finish(g0,u0,g1,u1,in.ctx);}
__device__ uint32_t observe(float x,uint32_t ctx,bool&valid){int n=__float2int_rn(x);valid=x==float(n)&&n>=-6391320&&n<=6391320;int u1=(n+131072)>>18;n-=262144*u1;int g1=(n+2048)>>12;n-=4096*g1;int u0=(n+32)>>6;int g0=n-64*u0;valid=valid&&g0>=-24&&g0<=24&&u0>=-24&&u0<=24&&g1>=-24&&g1<=24&&u1>=-24&&u1<=24;return finish(float(g0)*.5f,float(u0)*.5f,float(g1)*.5f,float(u1)*.5f,ctx);}

template<bool Validate>__global__ void native(uint32_t*out,const float4*rows,const float4*cols,unsigned long long*bad){int warp=(blockIdx.x*blockDim.x+threadIdx.x)/32;if(warp>=512)return;int lane=threadIdx.x%32,g=lane/4,t=lane%4,rb=(warp/32)*16,cb=(warp%32)*8;float4 r0=rows[rb+g],r1=rows[rb+g+8],x=cols[cb+g];bool first=t<2;float d[4]={};for(int group=0;group<2;group++){float a0=group?(first?r0.z:r0.w):(first?r0.x:r0.y),a1=group?(first?r1.z:r1.w):(first?r1.x:r1.y),b0=group?(first?x.z:x.w):(first?x.x:x.y);uint32_t a=__float_as_uint(a0*(group?4096.f:1.f)),b=__float_as_uint(a1*(group?4096.f:1.f)),c=__float_as_uint(b0);asm volatile("mma.sync.aligned.m16n8k8.row.col.f32.tf32.tf32.f32 {%0,%1,%2,%3},{%4,%5,%4,%5},{%6,%6},{%0,%1,%2,%3};":"+f"(d[0]),"+f"(d[1]),"+f"(d[2]),"+f"(d[3]):"r"(a),"r"(b),"r"(c));}for(int j=0;j<4;j++){int i=(rb+g+8*(j/2))*256+cb+2*t+j%2;Input in=input(i);bool valid;float x=d[j]*.25f;uint32_t y=observe(x,in.ctx,valid);if(Validate){uint32_t expected;uint32_t target=source(in,expected);if(!valid||__float_as_uint(x)!=expected)atomicAdd(bad,1ULL);else if(y!=target)atomicAdd(bad+1,1ULL);}out[i]=y;}}
__global__ void direct(uint32_t*out){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<N){uint32_t expected;out[i]=source(input(i),expected);}}
__global__ void prepare(uint32_t*table){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<N){uint32_t expected;table[i]=source(input(i),expected);}}
__global__ void lookup(uint32_t*out,const uint32_t*table){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<N)out[i]=table[i];}
__global__ void compare(const uint32_t*a,const uint32_t*b,unsigned long long*bad){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<N&&a[i]!=b[i])atomicAdd(bad+1,1ULL);}
