#define LAUNCH(M,STREAM) native<false><<<nb,256,0,STREAM>>>(out,rd,cd,bad)
LAUNCH(false,0);compare<<<db,256>>>(out,ref,bad);lookup<<<db,256>>>(out,table);compare<<<db,256>>>(out,ref,bad);CK(cudaDeviceSynchronize());CK(cudaMemcpy(counters,bad,16,cudaMemcpyDeviceToHost));if(counters[1])return 2;
auto prep2=Clock::now();cudaStream_t stream;CK(cudaStreamCreateWithFlags(&stream,cudaStreamNonBlocking));cudaGraph_t graphs[3];cudaGraphExec_t exec[3];for(int route=0;route<3;route++){CK(cudaStreamBeginCapture(stream,cudaStreamCaptureModeThreadLocal));for(int j=0;j<100;j++){if(route==0){LAUNCH(false,stream);}else if(route==1)direct<<<db,256,0,stream>>>(ref);else lookup<<<db,256,0,stream>>>(out,table);}CK(cudaStreamEndCapture(stream,&graphs[route]));CK(cudaGraphInstantiate(&exec[route],graphs[route],0));for(int j=0;j<5;j++)CK(cudaGraphLaunch(exec[route],stream));}CK(cudaStreamSynchronize(stream));auto prep3=Clock::now();cudaEvent_t start,end;CK(cudaEventCreate(&start));CK(cudaEventCreate(&end));std::vector<float>times[3];for(int round=0;round<7;round++)for(int j=0;j<3;j++){int route=(round+j)%3;CK(cudaEventRecord(start,stream));CK(cudaGraphLaunch(exec[route],stream));CK(cudaEventRecord(end,stream));CK(cudaEventSynchronize(end));float ms;CK(cudaEventElapsedTime(&ms,start,end));times[route].push_back(ms/100);}cudaFuncAttributes attrs[3];CK(cudaFuncGetAttributes(attrs+0,native<false>));CK(cudaFuncGetAttributes(attrs+1,direct));CK(cudaFuncGetAttributes(attrs+2,lookup));printf("{\"status\":\"pass\",\"cases\":65536,\"validation_checks\":%d,\"missing\":%llu,\"mismatches\":%llu,\"resident_label_bytes\":8192,\"source_oracle_fp4_bytes\":60,\"native_observer_table_bytes\":0,\"scale_table_bytes\":504,\"source_lookup_bytes\":262144,\"coordinate_axis_bytes\":2048,\"output_bytes\":262144,",N,counters[0],counters[1]);printf("\"preparation_ms\":{\"labels_observer_allocation_transfer_context\":%.6f,\"control_table_validation\":%.6f,\"graphs_warmup\":%.6f},\"timings_ms\":{",std::chrono::duration<double,std::milli>(prep1-prep0).count(),std::chrono::duration<double,std::milli>(prep2-prep1).count(),std::chrono::duration<double,std::milli>(prep3-prep2).count());const char*names[]={"two_serial_MMA_groups_analytic","direct_Q8","full_map_lookup"};for(int j=0;j<3;j++){std::sort(times[j].begin(